"""Cuaderno del estudiante, 8.º básico Lengua y Literatura, OA 18 (correferencia, elipsis y claridad)."""
from __future__ import annotations

from student_content_le8_c import E, L, MAT

OA18 = "LE08 OA 18"

L(OA18, 1,
  MAT,
  "Aprenderé a rastrear una cadena de referencia, es decir, todas las formas con que un texto nombra a la misma persona, cosa o idea, para saber si el texto se entiende.",
  ["Sé qué es un referente.", "Reconozco pronombres y sinónimos."],
  ["Una cadena de referencia es el conjunto de expresiones que, a lo largo de un texto, nombran el mismo referente. En «Marta llegó temprano. La joven abrió la tienda y ella ordenó las cajas», la cadena de Marta tiene tres eslabones: Marta, la joven y ella.",
   "Los eslabones pueden ser de distintos tipos: el nombre propio (Marta), un sinónimo o una expresión descriptiva (la joven), un pronombre (ella, lo, la) o un sujeto omitido (Marta llegó y saludó: el sujeto de «saludó» no está escrito, pero pertenece a la cadena). Un texto puede tener varias cadenas al mismo tiempo, una por cada referente.",
   "Para rastrear una cadena, elige un referente y subraya todo lo que lo nombra, de principio a fin. Luego verifica que cada eslabón apunte solo a ese referente. Si un eslabón puede apuntar a otro referente, la cadena se rompe y el lector se pierde. Rastrear cadenas es la primera tarea de una buena revisión."],
  [("cadena de referencia", "conjunto de expresiones que nombran el mismo referente en un texto"), ("eslabón", "cada expresión de una cadena de referencia"), ("referente", "persona, cosa o idea de la que se habla"), ("sujeto omitido", "sujeto que no está escrito, pero se deduce del verbo")],
  [("Contar eslabones", "¿Cuántos eslabones tiene la cadena de la tienda en «La tienda abrió. El local vendió pan y este negocio cerró a las ocho»?",
    ["Busco lo que nombra la tienda.", "Encuentro: La tienda, El local, este negocio.", "Cuento tres."],
    "3 eslabones"),
   ("Detectar una cadena rota", "En «La alcaldesa y el concejal visitaron la escuela. La autoridad saludó a los niños», ¿se mantiene la cadena de la alcaldesa?",
    ["«La autoridad» puede ser la alcaldesa o el concejal.", "Dos referentes posibles.", "La cadena se rompe."],
    "No: «La autoridad» puede apuntar a dos personas")],
  [("Confundir dos referentes que se parecen.", "Se usan expresiones generales como «la autoridad» cuando hay dos autoridades.", "Usa un nombre o un rasgo que distinga a cada referente."),
   ("Contar solo los nombres y olvidar los pronombres.", "Se piensa que «ella» no forma parte de la cadena.", "Los pronombres y los sujetos omitidos también son eslabones.")],
  ([E("En «El volcán despertó. El coloso lanzó ceniza y él cubrió el valle», ¿qué dos expresiones nombran al volcán además de «El volcán»?", "El coloso y él", "Ambas apuntan al mismo volcán."),
    E("¿Cuántos eslabones tiene la cadena de Marta en «Marta llegó temprano. La joven abrió la tienda y ella ordenó las cajas»?", "3", "Son Marta, La joven y ella."),
    E("¿Qué es una cadena de referencia: un conjunto de expresiones que nombran lo mismo o una lista de verbos?", "Un conjunto de expresiones que nombran lo mismo", "Los eslabones son expresiones con el mismo referente.")],
   [E("En «Los estudiantes montaron una feria. El grupo vendió pan y ellos regalaron volantes», ¿a quiénes se refiere «ellos»?", "A los estudiantes", "Es el mismo referente de «el grupo»."),
    E("En «Tomás y su perro Bruno caminaron. El niño llevaba una pelota y el animal la perseguía», ¿a quién pertenece la expresión «el animal»?", "A Bruno", "Un perro es un animal; Tomás es un niño."),
    E("¿Cuántos referentes distintos hay en «La biblioteca abrió. El edificio estaba lleno. Las estudiantes entraron»?", "2", "La biblioteca y el edificio son uno; las estudiantes son otro.")],
   [E("Elige la expresión que continúa la cadena de Valeria: «Valeria ganó el torneo. ___ recibió una medalla». Opciones: La campeona, Los jugadores.", "La campeona", "Nombra a Valeria, la ganadora."),
    E("Completa la cadena: «El puma desapareció entre los árboles. El ___ regresó al amanecer». Opciones: felino, bosque.", "felino", "Un puma es un felino; el bosque es otro referente."),
    E("¿Cuántas veces retoma el cuaderno el pronombre «lo» en «Ema compró un cuaderno. Lo forró y lo guardó. Después Ema lo usó»?", "3", "Los tres «lo» retoman el cuaderno.")],
   [E("En «La alcaldesa y el concejal visitaron la escuela. La autoridad saludó a los niños», ¿qué expresión vuelve dudosa la cadena?", "La autoridad", "Podría nombrar a cualquiera de las dos personas."),
    E("En «Pedro llegó y saludó», ¿el sujeto omitido de «saludó» pertenece a la cadena de Pedro?", "Sí", "El verbo tiene el mismo sujeto, aunque no esté escrito.")],
   [E("¿Cuántos eslabones tiene la cadena de Valeria, sin contar el nombre, en «Valeria ganó. La campeona sonrió. Ella agradeció. Los compañeros de curso la abrazaron»?", "3", "Son La campeona, Ella y la."),
    E("Reescribe usando sujeto omitido para evitar repeticiones: «Matías pidió permiso. Matías salió. Matías volvió».", "Matías pidió permiso, salió y volvió.", "El sujeto omitido mantiene la cadena sin repetir el nombre.")]),
  [E("Un cartel de senderismo dice: «El sendero parte en la plaza. Este sendero lleva al mirador; el camino termina en una cascada». ¿Cuántas expresiones distintas nombran al sendero?", "3", "Son El sendero, Este sendero y el camino.")],
  [E("¿Un pronombre puede ser eslabón de una cadena de referencia?", "Sí", "Retoma el referente igual que un nombre."),
   E("¿Qué pasa si un eslabón puede apuntar a dos referentes: la cadena se mantiene o se rompe?", "Se rompe", "El lector ya no sabe a cuál se refiere."),
   E("Para rastrear una cadena, ¿qué haces primero: subrayar todo lo que nombra el referente o cambiar los verbos?", "Subrayar todo lo que nombra el referente", "Así ves la cadena completa.")],
  ("Lee este texto de ejemplo: «El colegio organizó una feria científica. El establecimiento invitó a las familias y estas llegaron temprano. La directora presentó el programa y ella agradeció a los estudiantes. Los jóvenes mostraron sus experimentos». 1) Subraya con un color la cadena del colegio y con otro la cadena de los estudiantes. 2) Cuenta los eslabones de cada cadena. 3) Escribe una oración que agregue un eslabón nuevo a la cadena de la directora sin generar duda.",
   "Cadena del colegio: El colegio, El establecimiento (2). Cadena de los estudiantes: los estudiantes, Los jóvenes (2). Oración nueva: «La autoridad del colegio cortó la cinta», solo si no hay otra autoridad; si hay duda, usar «La directora cortó la cinta».",
   ["subraya cadenas completas", "cuenta bien los eslabones", "agrega un eslabón sin ambigüedad"], ["texto subrayado", "oración nueva"], ["olvidar los pronombres", "agregar un eslabón que apunta a otro referente"], "Pide a otra persona que lea la oración nueva y diga quién es el referente."),
  "Elige un párrafo de un libro de tu casa y marca una cadena de referencia completa.",
  "Escribe un párrafo de cuatro oraciones con dos cadenas de referencia distintas y márcalas con colores.")

L(OA18, 2,
  MAT,
  "Aprenderé a distinguir pronombres personales tónicos y átonos, y a usarlos para evitar repeticiones sin perder el referente.",
  ["Reconozco pronombres personales.", "Sé qué es una cadena de referencia."],
  ["Los pronombres personales tónicos tienen acento propio y pueden aparecer solos o con preposición: yo, tú, él, ella, nosotros, ellos, mí, ti, sí, conmigo, contigo. Los pronombres átonos se apoyan en el verbo y no se usan solos: me, te, lo, la, le, se, nos, los, las, les. Los tónicos dan énfasis o contraste; los átonos reemplazan un complemento sin repetirlo.",
   "Reglas útiles: «lo/la/los/las» sustituyen al complemento directo («Vi a María» → «La vi»), y «le/les» al complemento indirecto («Di el libro a Pedro» → «Le di el libro»). Si hay ambos, aparece «se» antes de «lo»: «Regalé las flores a mi tía» → «Se las regalé». Con la preposición «con», la forma es conmigo o contigo, no «con mí». Además, «mí» lleva tilde cuando es pronombre («es para mí»); sin tilde, «mi» es posesivo.",
   "Un pronombre átono puede crear ambigüedad si hay dos referentes posibles: «Vi a Pedro y a Luis. Lo saludé» no aclara a cuál. Un exceso de tónicos también molesta: «Yo creo que yo puedo» suena repetitivo. Se usa el tónico cuando aporta contraste: «A mí me gusta el té; a ti, el café»."],
  [("pronombre tónico", "pronombre con acento propio, como «ella» o «mí»"), ("pronombre átono", "pronombre que se apoya en el verbo, como «lo» o «me»"), ("complemento directo", "lo que recibe directamente la acción del verbo"), ("complemento indirecto", "la persona o cosa que recibe el beneficio o daño de la acción")],
  [("Sustituir dos complementos", "Reemplaza los complementos de «Entregué los informes a la directora».",
    ["El complemento directo es «los informes» → «los».", "El complemento indirecto es «a la directora» → «le».", "Cuando van juntos, «le» pasa a «se»: Se los entregué."],
    "Se los entregué."),
   ("Elegir la forma con preposición", "Completa: «Ven ___ al parque» (con + yo).",
    ["Con la preposición «con» se usa una forma especial.", "No se dice «con mí».", "Se dice «conmigo»."],
    "conmigo")],
  [("Escribir «le los» en lugar de «se los».", "Se mantienen las formas por separado.", "Cuando «le» o «les» va antes de «lo/la/los/las», se cambia por «se»."),
   ("Escribir «con mí» o «con ti».", "Se aplica la regla de las demás preposiciones.", "Con «con», las formas son conmigo, contigo y consigo.")],
  ([E("¿«Me» es pronombre tónico o átono?", "Átono", "Se apoya en el verbo y no se usa solo."),
    E("¿«Ella» es pronombre tónico o átono?", "Tónico", "Tiene acento propio y puede aparecer solo."),
    E("En «A mí me encanta leer», ¿cuál es el pronombre tónico?", "A mí", "El otro, «me», es átono.")],
   [E("Completa con «lo» o «la»: «Vi a María y ___ saludé».", "la", "Sustituye a «a María», complemento directo femenino singular."),
    E("En «Le di el cuaderno a Pedro», ¿a quién sustituye «le»?", "A Pedro", "Es el complemento indirecto."),
    E("En «Vi a Pedro y a Luis. Lo saludé», ¿qué problema tiene «lo»?", "No se sabe a cuál de los dos se refiere", "Hay dos referentes masculinos posibles.")],
   [E("Reescribe con pronombres átonos: «Regalé las flores a mi tía».", "Se las regalé.", "«Las flores» pasa a «las»; «a mi tía» pasa a «se» antes de «las»."),
    E("Completa con la forma correcta: «Esta carta es para ___ (yo)».", "mí", "Con la preposición «para» se usa «mí» con tilde."),
    E("Completa: «Quiero que vengas con ___ (yo)».", "conmigo", "Con «con» se usa conmigo.")],
   [E("Versión 1: «A mí me gusta el té; a ti, el café.» Versión 2: «Yo creo que yo puedo.» ¿En cuál el pronombre tónico aporta contraste?", "En la versión 1", "Marca la diferencia entre dos gustos; en la versión 2 solo repite."),
    E("¿Cuántos pronombres átonos hay en «Me lo dijo y te lo repetirá»?", "4", "Son me, lo, te y lo.")],
   [E("Reescribe con pronombres: «Entregué los trabajos a los profesores».", "Se los entregué.", "«Los trabajos» pasa a «los»; «a los profesores» a «se»."),
    E("Un compañero escribe «Le los di a Ana». ¿Cuál es la forma correcta?", "Se los di a Ana.", "Antes de «los», «le» cambia a «se».")]),
  [E("Una nota dice: «Carlos, te dejé el libro sobre la mesa; ven a buscarlo conmigo». ¿A quién se refiere «te»?", "A Carlos", "Es la persona a quien se dirige la nota.")],
  [E("¿«Conmigo» es una forma correcta o incorrecta?", "Correcta", "Es la forma especial con la preposición «con»."),
   E("¿Cuál va antes de «lo»: «le» o «se»?", "Se", "«Se lo» reemplaza a «le lo»."),
   E("¿Los pronombres átonos se usan solos?", "No", "Siempre se apoyan en el verbo.")],
  ("Lee este texto de ejemplo: «Julieta le entregó la carta a su abuelo. Julieta le leyó la carta a su abuelo y él la guardó. Julieta le dijo a su abuelo que Julieta lo quería mucho». 1) Reescríbelo con pronombres átonos para evitar las repeticiones. 2) Marca los pronombres tónicos y átonos que usaste. 3) Revisa que ninguno genere ambigüedad.",
   "Julieta le entregó la carta a su abuelo. Se la leyó y él la guardó. Le dijo que lo quería mucho. Átonos: le, se, la, la, le, lo. Tónico: él. No hay ambigüedad porque hay una sola mujer y un solo hombre.",
   ["usa «se la» y no «le la»", "no deja pronombres ambiguos", "distingue tónicos y átonos"], ["texto reescrito", "pronombres marcados"], ["escribir «le la»", "dejar «lo» sin referente claro"], "Lee en voz alta tu versión y comprueba que suene natural y sin repeticiones."),
  "Elige una frase de un mensaje tuyo y cámbiala usando dos pronombres átonos.",
  "Escribe tres oraciones donde un pronombre tónico aporte contraste y otras tres donde sobre.")

L(OA18, 3,
  MAT,
  "Aprenderé a retomar una idea con sustitución pronominal, sustitución léxica y nominalización, y a elegir el recurso que mantiene el referente claro.",
  ["Reconozco cadenas de referencia.", "Conozco sinónimos y pronombres."],
  ["La sustitución consiste en reemplazar una expresión por otra que nombra lo mismo. Puede ser pronominal («Compré una bicicleta. La pinté de verde») o léxica, con un sinónimo o una palabra más general («el felino» por «el puma»). La nominalización convierte un verbo o un adjetivo en sustantivo para retomar una idea completa: «Subieron los precios. Esa subida preocupó a las familias».",
   "Algunas nominalizaciones comunes son: decidir → decisión, aumentar → aumento, construir → construcción, descubrir → descubrimiento, llegar → llegada, proteger → protección, lento → lentitud. Al nominalizar, el sustantivo resume la oración anterior; por eso suele ir acompañado de «este», «ese» o «aquel»: «Esta decisión», «Ese descubrimiento».",
   "Para usar bien estos recursos, comprueba tres cosas: que el nuevo término nombre lo mismo, que no haya otra idea a la cual pueda apuntar y que no cambie el sentido. «Los vecinos limpiaron la playa y pintaron el muro. La limpieza duró dos días» es claro, porque «la limpieza» solo retoma el primer hecho."],
  [("sustitución", "reemplazo de una expresión por otra que nombra lo mismo"), ("nominalización", "paso de un verbo o adjetivo a sustantivo para retomar una idea"), ("sinónimo", "palabra de significado cercano a otra"), ("resumir", "decir lo esencial de una idea en pocas palabras")],
  [("Nominalizar un verbo", "Completa: «Los científicos descubrieron una especie. Este ___ cambió el mapa de la zona».",
    ["El verbo es «descubrir».", "El sustantivo derivado es «descubrimiento».", "Lleva «este» porque es masculino singular."],
    "descubrimiento"),
   ("Comprobar el referente", "En «Los vecinos limpiaron la playa y pintaron el muro. La limpieza duró dos días», ¿qué hecho retoma «la limpieza»?",
    ["«Limpieza» viene de limpiar.", "El texto dice que limpiaron la playa.", "Pintar el muro es otro hecho."],
    "Limpiar la playa")],
  [("Usar «esto» o «eso» sin que se sepa qué retoman.", "Hay varias ideas anteriores posibles.", "Reemplaza «esto» por una nominalización precisa."),
   ("Inventar una nominalización que no existe, como «decidimiento».", "Se agrega el sufijo por intuición.", "Comprueba en el diccionario: decidir → decisión.")],
  ([E("¿Cuál es el sustantivo derivado de «decidir»?", "Decisión", "Es la nominalización usual de ese verbo."),
    E("¿Cuál es el sustantivo derivado de «aumentar»?", "Aumento", "Resume la acción de que algo suba."),
    E("¿«Construcción» viene de «construir» o de «constar»?", "De construir", "Nombra la acción de construir.")],
   [E("En «El equipo ganó el torneo. Esa victoria alegró al barrio», ¿qué retoma «esa victoria»?", "Que el equipo ganó el torneo", "Resume toda la oración anterior."),
    E("En «Subieron los precios del pan. Esta subida preocupó a las familias», ¿qué retoma «esta subida»?", "Que subieron los precios del pan", "Es la nominalización de «subieron»."),
    E("En «Compré una bicicleta. La pinté de verde», ¿qué tipo de sustitución es «la»?", "Pronominal", "Un pronombre toma el lugar de «una bicicleta».")],
   [E("Completa con una nominalización de «llegar»: «Los turistas llegaron al puerto. Su ___ llenó los hoteles».", "llegada", "Resume la acción de llegar."),
    E("Completa con una nominalización de «prohibir»: «La municipalidad prohibió fumar en la plaza. Esa ___ rige desde hoy».", "prohibición", "Resume la acción de prohibir."),
    E("Elige el sustantivo de «proteger»: protección, protegimiento.", "protección", "Es la forma que existe en español.")],
   [E("Para «descubrir», ¿cuál es la nominalización correcta: descubrimiento o descubrición?", "Descubrimiento", "«Descubrición» no existe."),
    E("En «Los vecinos limpiaron la playa y pintaron el muro. La limpieza duró dos días», ¿por qué «la limpieza» es clara?", "Porque solo puede retomar el hecho de limpiar la playa", "El otro hecho es pintar, que no se nombra «limpieza».")],
   [E("Une en dos oraciones usando una nominalización: «Los precios subieron. Esto afectó a los compradores».", "La subida de los precios afectó a los compradores.", "«Subida» resume «subieron los precios»."),
    E("Escribe el sustantivo derivado del adjetivo «lento».", "Lentitud", "Nombra la cualidad de ser lento.")]),
  [E("Un artículo dice: «La municipalidad decidió cerrar la plaza. Esa ___ molestó a los comerciantes». Completa con la nominalización.", "decisión", "Retoma que la municipalidad decidió.")],
  [E("¿La nominalización convierte un verbo en un sustantivo?", "Sí", "Por ejemplo, llegar → llegada."),
   E("¿Qué sirve para comprobar una sustitución: que nombre lo mismo o que suene bonito?", "Que nombre lo mismo", "El referente debe mantenerse."),
   E("¿«Ese descubrimiento» retoma una idea completa?", "Sí", "Nominaliza la oración anterior.")],
  ("Lee este texto de ejemplo: «El museo abrió una exposición. El museo recibió miles de visitas. La exposición mostraba fósiles. El museo decidió extender la exposición». 1) Reemplaza dos repeticiones con sustitución léxica. 2) Nominaliza una idea con «esta» o «ese». 3) Explica por qué el referente se mantiene claro.",
   "El museo abrió una exposición. El recinto recibió miles de visitas. La muestra mostraba fósiles. Esta buena acogida llevó al museo a extenderla. «El recinto» y «la muestra» nombran lo mismo; «esta buena acogida» resume que recibió miles de visitas.",
   ["usa dos sustituciones precisas", "nominaliza una idea", "explica por qué no se pierde el referente"], ["texto reescrito", "justificación de una frase"], ["usar un término que nombra otra cosa", "usar «esto» sin referente claro"], "Pide a otra persona que diga qué retoma cada expresión nueva."),
  "Busca en un diario o revista una nominalización que retome una oración completa y escríbela con su verbo de origen.",
  "Escribe un párrafo de cuatro oraciones usando una sustitución pronominal, una léxica y una nominalización.")

L(OA18, 4,
  MAT,
  "Aprenderé a evaluar la elipsis, es decir, la omisión de palabras que el lector puede recuperar, y a decidir cuándo ayuda y cuándo confunde.",
  ["Sé qué es el sujeto omitido.", "Reconozco una cadena de referencia."],
  ["La elipsis es la omisión de una palabra o grupo de palabras que el lector puede deducir. En «Ana compró manzanas y Luis, peras», se omite el verbo «compró» en la segunda parte. En «Llegamos tarde, pero cenamos igual», se omite el sujeto «nosotros» en las dos formas verbales.",
   "La elipsis ayuda porque evita repeticiones y hace el texto más ágil. Pero solo funciona si el elemento omitido se recupera con seguridad, y si el verbo omitido concuerda con el sujeto nuevo: «Los chicos juegan fútbol y las chicas, vóleibol» omite «juegan», que concuerda con «las chicas». Si el elemento omitido puede ser dos cosas, la elipsis confunde.",
   "Compara: «Julián vio a Pablo y se rio». ¿Quién se rio, Julián o Pablo? La elipsis del sujeto genera duda. La corrección es nombrar: «Julián vio a Pablo y Julián se rio». Para evaluar una elipsis, pregúntate: ¿qué palabra falta?, ¿hay una sola posibilidad?, ¿la forma verbal concuerda? Si las tres respuestas son claras, la elipsis está bien."],
  [("elipsis", "omisión de una palabra que el lector puede deducir"), ("recuperar", "deducir una palabra omitida a partir del texto"), ("concordancia", "acuerdo de número y persona entre sujeto y verbo"), ("ágil", "que se lee con fluidez, sin repeticiones")],
  [("Recuperar el verbo omitido", "¿Qué verbo se omite en «Mi hermana toca el piano y yo, la guitarra»?",
    ["En la segunda parte falta un verbo.", "Es el mismo verbo de la primera.", "Pero debe concordar con «yo»: toco."],
    "toco"),
   ("Detectar elipsis ambigua", "En «Julián vio a Pablo y se rio», ¿la elipsis del sujeto es clara?",
    ["Hay dos sujetos posibles.", "No sabemos cuál se rio.", "La elipsis es ambigua."],
    "No: puede ser Julián o Pablo")],
  [("Omitir una palabra que no se puede recuperar.", "Se asume que el lector adivinará.", "Omite solo lo que tenga una única posibilidad."),
   ("Omitir un verbo sin ajustar la concordancia.", "Se copia la forma de la primera parte.", "Piensa el verbo omitido con el sujeto nuevo: «yo toco», no «yo toca».")],
  ([E("En «Ana compró manzanas y Luis, peras», ¿qué verbo se omite?", "compró", "Es el mismo verbo de la primera parte."),
    E("En «Llegamos tarde, pero cenamos igual», ¿cuál es el sujeto omitido?", "Nosotros", "Las terminaciones indican primera persona del plural."),
    E("¿La elipsis es omitir una palabra que el lector puede deducir o una palabra que no se entiende?", "Una palabra que el lector puede deducir", "Si no se puede deducir, la elipsis confunde.")],
   [E("En «Mi hermano estudia medicina y mi prima, derecho», ¿qué verbo se recupera?", "estudia", "Concuerda con «mi prima», singular."),
    E("En «Julián vio a Pablo y se rio», ¿se puede recuperar con seguridad quién se rio?", "No", "El sujeto podría ser Julián o Pablo."),
    E("En «Los chicos juegan fútbol y las chicas, vóleibol», ¿en qué forma se recupera el verbo?", "juegan", "Concuerda con «las chicas», plural.")],
   [E("Simplifica con elipsis: «Marta leyó un cuento y Marta lo comentó con sus amigas».", "Marta leyó un cuento y lo comentó con sus amigas.", "Se omite el segundo sujeto, que es el mismo."),
    E("Simplifica con elipsis del verbo: «Sofía pintó el cielo y Daniel pintó el mar».", "Sofía pintó el cielo y Daniel, el mar.", "Se omite «pintó» en la segunda parte."),
    E("¿Cuántas palabras se omiten en «Rosa vive en Arica y Mateo, en Iquique»? Considera solo el verbo.", "1", "Se omite «vive».")],
   [E("Aclara la elipsis ambigua: «Julián vio a Pablo y se rio» (se rio Pablo).", "Julián vio a Pablo y Pablo se rio.", "Nombrar al sujeto elimina la duda."),
    E("En «Mis tíos viven en Osorno y mi prima, en Valdivia», ¿en qué forma debe recuperarse el verbo para «mi prima»?", "vive", "Debe concordar con «mi prima», singular, no con «mis tíos».")],
   [E("«El lunes iré al médico y el martes, al dentista.» ¿Qué verbo se recupera y en qué forma?", "iré", "Concuerda con el sujeto «yo»."),
    E("Reescribe con elipsis del verbo: «Lucía dibuja un gato y Tomás dibuja un perro».", "Lucía dibuja un gato y Tomás, un perro.", "Se omite «dibuja» en la segunda parte.")]),
  [E("Un letrero dice: «Los estudiantes de 7.º entran por la puerta norte y los de 8.º, por la sur». ¿Por dónde entran los de 8.º?", "Por la puerta sur", "Se omiten «entran» y «puerta», que se recuperan.")],
  [E("¿La elipsis funciona cuando la palabra omitida se puede deducir con seguridad?", "Sí", "Esa es la condición básica."),
   E("¿Qué debe cumplir el verbo omitido: concordar con el sujeto nuevo o con el anterior?", "Con el sujeto nuevo", "«Yo toco», no «yo toca»."),
   E("¿La elipsis ambigua se corrige nombrando al sujeto o borrando más palabras?", "Nombrando al sujeto", "Así se elimina la duda.")],
  ("Lee este texto de ejemplo: «Pedro invitó a Joaquín al cine. Pedro compró las entradas y Joaquín compró las palomitas. Pedro vio a Joaquín y se fue». En la última oración, quien se fue es Joaquín. 1) Aplica elipsis donde sea segura. 2) Indica dónde la elipsis no es segura y qué harías. 3) Explica cada decisión en una frase.",
   "Pedro invitó a Joaquín al cine. Pedro compró las entradas y Joaquín, las palomitas. En la última oración hay que nombrar al sujeto: «Pedro vio a Joaquín y Joaquín se fue». La elipsis del verbo es segura porque ambos compraron; la del sujeto de «se fue» no lo es.",
   ["aplica elipsis seguras", "detecta la elipsis ambigua", "justifica cada decisión"], ["texto con elipsis", "tres justificaciones"], ["omitir sin comprobar", "olvidar la concordancia"], "Pide a otra persona que diga qué palabra se omitió en cada caso."),
  "Busca en un cuento de tu casa una oración con verbo omitido y escribe la oración completa.",
  "Escribe dos oraciones con elipsis segura y dos con elipsis dudosa, y corrige las dudosas.")

L(OA18, 5,
  MAT,
  "Aprenderé a revisar la claridad y el estilo de un texto: encontrar dónde se pierde el referente, dónde cambia el sentido y dónde un recurso suena pesado.",
  ["Conozco los recursos de correferencia.", "Sé qué es la elipsis."],
  ["Revisar un texto tiene tres focos. El primero es la pérdida del referente: el lector no sabe a quién apunta un pronombre, una elipsis o una sustitución. El segundo es el cambio de sentido: la nueva expresión nombra otra cosa o agrega un dato falso («la niña» por «la ministra»). El tercero es el estilo: demasiadas repeticiones, demasiados pronombres o demasiadas nominalizaciones vagas hacen el texto pesado o confuso.",
   "Para cada problema hay una solución. La pérdida de referente se corrige nombrando, reordenando o usando discurso directo. El cambio de sentido se corrige eligiendo una expresión que nombre exactamente lo mismo. El problema de estilo se corrige variando los recursos: alterna nombre, pronombre y expresión descriptiva, pero sin llegar a la ambigüedad.",
   "Un buen revisor pregunta primero «¿se entiende?» y después «¿suena bien?». Claridad antes que elegancia: una repetición necesaria vale más que un pronombre dudoso. Al terminar, compara el texto inicial con el final y comprueba que no cambió lo que se quería decir."],
  [("pérdida del referente", "cuando el lector no sabe a quién se refiere una expresión"), ("cambio de sentido", "cuando una expresión nombra algo distinto de lo que se quería"), ("estilo", "modo de escribir que hace un texto ágil o pesado"), ("reordenar", "cambiar el orden de las palabras para aclarar")],
  [("Clasificar el problema", "¿Qué problema tiene «Teo compró pan. Teo llevó el pan a casa. Teo comió el pan»?",
    ["Entiendo todo: no hay duda del referente.", "Pero «Teo» y «el pan» se repiten tres veces.", "Es un problema de estilo."],
    "Problema de estilo: repeticiones"),
   ("Arreglar un cambio de sentido", "Corrige «La ministra llegó. La niña saludó» si se habla de la misma persona.",
    ["«La niña» cambia la edad.", "Debo nombrar a la misma ministra.", "Uso «Ella» o «La autoridad»."],
    "La ministra llegó. Ella saludó.")],
  [("Corregir solo la repetición y crear una ambigüedad.", "Se reemplaza todo por pronombres.", "Después de corregir, vuelve a rastrear la cadena."),
   ("Pensar que repetir siempre es un error.", "Se confunde claridad con variedad.", "Una repetición necesaria es mejor que un pronombre dudoso.")],
  ([E("¿«Teo compró pan. Teo llevó el pan. Teo comió el pan» tiene pérdida de referente o problema de estilo?", "Problema de estilo", "Se repite demasiado, pero no hay duda."),
    E("«Marta habló con Sara y ella se fue.» ¿Qué problema tiene?", "Pérdida del referente", "No se sabe quién se fue."),
    E("«La ministra llegó. La niña saludó.» ¿Qué problema tiene, si es la misma persona?", "Cambio de sentido", "«La niña» nombra a otra persona.")],
   [E("¿Cuál se corrige variando recursos: pérdida del referente o problema de estilo?", "Problema de estilo", "Se alterna nombre, pronombre y expresión descriptiva."),
    E("«El tren se retrasó, la lluvia no paró y la reunión se suspendió. Esto enojó al jefe.» ¿Qué problema tiene «esto»?", "Pérdida del referente", "No se sabe cuál de los tres hechos enojó al jefe."),
    E("¿Qué se pregunta primero un buen revisor: ¿se entiende? o ¿suena bonito?", "¿Se entiende?", "La claridad va antes que la elegancia.")],
   [E("Corrige la pérdida del referente: «Marta habló con Sara y ella se fue» (se fue Sara).", "Marta habló con Sara y Sara se fue.", "Se nombra a quien se fue."),
    E("Corrige el problema de estilo: «Teo compró pan. Teo llevó el pan a casa. Teo comió el pan». Usa pronombres y elipsis.", "Teo compró pan, lo llevó a casa y se lo comió.", "El sujeto omitido y los pronombres reducen la repetición."),
    E("Corrige el cambio de sentido: «El profesor Díaz entró. El joven saludó» (se habla del profesor).", "El profesor Díaz entró. Él saludó.", "Un profesor no se nombra «el joven» sin más datos.")],
   [E("Una revisora quiere cambiar «El perro ladró» por «Él ladró» en «Vi un perro y un gato. El perro ladró». ¿Se mantiene la claridad?", "No", "«Él» puede ser el perro o el gato, ambos masculinos."),
    E("¿Es mejor mantener una repetición necesaria o usar un pronombre dudoso?", "Mantener la repetición", "La claridad es más importante.")],
   [E("Cuenta cuántos problemas tiene: «Lucía vio a Rosa y se fue. Las dos estaban tristes. La niña estaba cansada». Considera el sujeto dudoso y el cambio a «la niña» si ambas son adultas.", "2", "«Se fue» es dudoso y «la niña» cambia el dato."),
    E("Reescribe: «Lucía vio a Rosa y se fue» (se fue Lucía).", "Lucía vio a Rosa y Lucía se fue.", "Se nombra el sujeto para evitar duda.")]),
  [E("Un aviso escolar dice: «Los estudiantes de séptimo y octavo ensayan juntos. Ellos tendrán la presentación el viernes». ¿Qué problema posible tiene «ellos»?", "Podría apuntar a séptimo, a octavo o a ambos", "No hay una única lectura.")],
  [E("¿Un problema de estilo puede no ser una ambigüedad?", "Sí", "Puede ser solo repetición o pesadez."),
   E("¿Qué se hace con un cambio de sentido: se elige una expresión que nombre lo mismo o se agregan más repeticiones?", "Se elige una expresión que nombre lo mismo", "Se recupera el referente original."),
   E("Después de corregir, ¿qué conviene hacer: releer el texto completo o entregarlo?", "Releer el texto completo", "Así se comprueba que no se creó otro problema.")],
  ("Revisa este texto de ejemplo: «El club de ajedrez se reunió. El club de ajedrez eligió a Paula y a Inés como capitanas. Ella dijo que su equipo ganaría. La niña ofreció unas galletas». Anota cada problema (pérdida de referente, cambio de sentido o estilo) y escribe la versión corregida.",
   "Problemas: repetición de «El club de ajedrez» (estilo); «ella» y «su» ambiguos (pérdida del referente); «la niña» (cambio de sentido). Versión: «El club de ajedrez se reunió y eligió a Paula y a Inés como capitanas. Paula dijo que su equipo ganaría. Inés ofreció unas galletas».",
   ["nombra el tipo de problema", "corrige sin crear un problema nuevo", "relee el texto final"], ["lista de problemas", "versión final"], ["corregir solo uno de los problemas", "cambiar lo que se quería decir"], "Pide a otra persona que lea la versión final y diga si hay dudas."),
  "Revisa un mensaje que escribiste esta semana y marca si tiene pérdida de referente, cambio de sentido o problema de estilo.",
  "Escribe un párrafo con tres problemas de claridad a propósito y su versión corregida.")

L(OA18, 6,
  MAT,
  "Aprenderé a justificar por escrito mis decisiones de cohesión, explicando qué recurso usé, qué problema evité y qué riesgo comprobé.",
  ["Conozco los recursos de correferencia.", "Sé revisar la claridad y el estilo de un texto."],
  ["Justificar una decisión es explicar por qué elegiste un recurso y no otro. Una buena justificación tiene tres partes: nombrar el recurso («usé un sinónimo»), decir qué problema evita («evito repetir tres veces el mismo nombre») y comprobar el riesgo («no hay otra persona a la que pueda apuntar»).",
   "Por ejemplo, para el texto «Ana habló con Marta y ella se fue», una justificación completa sería: «Reemplacé el pronombre por el nombre porque «ella» podía ser Ana o Marta; ahora el lector no duda». En cambio, «Lo cambié porque sonaba mejor» no es suficiente, porque no dice qué problema se resolvió.",
   "También puedes justificar mantener un recurso: «Dejé la repetición de «máquina B» porque hay dos máquinas y la letra las distingue». Justificar decisiones muestra que el texto no es casual: cada elección tiene un propósito y se puede defender con evidencia del texto."],
  [("justificar", "explicar con razones por qué se tomó una decisión"), ("recurso", "herramienta del lenguaje, como un pronombre o una elipsis"), ("evidencia", "dato del texto que apoya una decisión"), ("riesgo", "posible problema que hay que comprobar")],
  [("Justificar un cambio", "Justifica el cambio de «Ana habló con Marta y ella se fue» a «Ana habló con Marta y Marta se fue».",
    ["Nombro el recurso: repetí el nombre.", "Digo el problema: «ella» podía ser Ana o Marta.", "Compruebo el riesgo: ahora solo hay una posibilidad."],
    "Repetí el nombre porque «ella» podía ser Ana o Marta; ahora no hay duda"),
   ("Justificar una repetición", "Justifica mantener «la máquina B» en «Se probó la máquina A y la máquina B. La máquina B falló».",
    ["El recurso es mantener el nombre.", "El problema que evita: confundir las dos máquinas.", "El riesgo comprobado: si lo cambio por «ella», no se sabría cuál."],
    "Mantuve la repetición porque hay dos máquinas y la letra las distingue")],
  [("Justificar con «sonaba mejor».", "No se nombra el problema ni el recurso.", "Di qué problema resolviste y cómo lo comprobaste."),
   ("Justificar un recurso que no resolvió el problema.", "Se explica una decisión que no mejoró nada.", "Comprueba que el texto realmente quedó más claro.")],
  ([E("¿Cuál es la primera parte de una buena justificación: nombrar el recurso o decir que sonaba mejor?", "Nombrar el recurso", "Se parte por decir qué recurso se usó."),
    E("¿Qué debe incluir una justificación: el problema evitado o la fecha?", "El problema evitado", "Explica por qué se tomó la decisión."),
    E("¿Se puede justificar mantener una repetición?", "Sí", "Si evita una confusión, es una decisión válida.")],
   [E("¿Cuál justificación es suficiente: «Lo cambié porque sonaba mejor» o «Reemplacé el pronombre porque podía apuntar a dos personas»?", "Reemplacé el pronombre porque podía apuntar a dos personas", "Nombra el recurso y el problema."),
    E("«Dejé «máquina B» porque hay dos máquinas y la letra las distingue.» ¿Qué decisión se justifica?", "Mantener una repetición", "Se explica por qué no se cambió."),
    E("¿Qué parte comprueba el riesgo: «ahora solo hay una posibilidad» o «lo cambié»?", "Ahora solo hay una posibilidad", "Verifica que el problema se resolvió.")],
   [E("En «El museo abrió. El museo recibió visitas. El museo cerró», ¿qué expresión se repite tres veces y conviene variar?", "El museo", "Es la expresión repetida en las tres oraciones."),
    E("Un estudiante cambió «el pintor» por «él» en «Luis vio al pintor. Él sonrió». Justifica en una frase por qué podría ser un problema.", "Porque «él» puede apuntar a Luis o al pintor", "Hay dos referentes masculinos."),
    E("¿Qué recurso se justifica con «Eliminé el nombre repetido porque el sujeto sigue siendo el mismo»?", "Elipsis del sujeto", "Omitir un sujeto recuperable es elipsis.")],
   [E("Un estudiante justifica: «Cambié «ministra» por «niña» porque quería variar». ¿Es una buena justificación?", "No", "«Niña» cambia el sentido y varía sin criterio."),
    E("¿La justificación «Mantuve la repetición» debe incluir el motivo o basta decir que lo mantuvo?", "Debe incluir el motivo", "Sin motivo no hay justificación.")],
   [E("Evalúa: «Reemplacé «ella» por «Marta» porque dudaba entre Ana y Marta». ¿Tiene recurso, problema y riesgo comprobado?", "Tiene recurso y problema; le falta comprobar el riesgo", "No dice si ahora queda una sola posibilidad."),
    E("«Usé el sinónimo «el recinto» para «el museo», porque repetía mucho.» ¿Qué riesgo falta comprobar?", "Que «el recinto» no pueda apuntar a otro lugar del texto", "Un sinónimo debe apuntar a un solo referente.")]),
  [E("Una compañera justifica: «Cambié «el científico» por «Rodrigo» porque en el texto hay dos científicos y el nombre los distingue». ¿Qué problema evitó?", "La ambigüedad entre dos científicos", "El nombre propio deja un único referente.")],
  [E("¿Justificar es explicar con razones por qué se tomó una decisión?", "Sí", "Esa es la definición."),
   E("¿Qué tres partes tiene una buena justificación?", "Recurso, problema evitado y riesgo comprobado", "Son las tres partes que se enseñaron."),
   E("¿«Porque sonaba mejor» es una justificación suficiente?", "No", "No dice qué problema resolvió.")],
  ("Lee este texto de ejemplo y su versión corregida. Original: «Rita habló con Camila y ella aceptó. El grupo trabajó mucho. El grupo terminó temprano». Corregido: «Rita habló con Camila y Camila aceptó. El grupo trabajó mucho y terminó temprano». Escribe tres justificaciones, una por cada cambio, con recurso, problema evitado y riesgo comprobado.",
   "1) Reemplacé «ella» por «Camila» porque «ella» podía ser Rita o Camila; ahora solo hay una posibilidad. 2) Usé un sujeto omitido en «terminó temprano» para no repetir «El grupo»; el sujeto es el mismo. 3) Mantuve «Camila» y no «la joven» porque otro título podría apuntar a Rita.",
   ["nombra el recurso", "explica el problema evitado", "comprueba el riesgo"], ["tres justificaciones"], ["decir «sonaba mejor»", "no comprobar el riesgo"], "Pide a otra persona que lea cada justificación y diga si convence."),
  "Elige tres cambios que harías a un mensaje tuyo y escribe una justificación para cada uno.",
  "Escribe un texto corto con una repetición necesaria y justifica por qué la dejaste.")
